window.NOTES={"version":44,"chapters":[{"number":1,"title":"信息技术与计算机文化","summary":"计算机发展、信息表示、硬件、软件与计算机系统的基础概念。","sections":[{"id":"1.1","title":"信息与信息技术"},{"id":"1.2","title":"计算机技术概论"},{"id":"1.3","title":"计算机中信息的表示"},{"id":"1.4","title":"计算机系统"},{"id":"1.5","title":"微型计算机系统"}]},{"number":2,"title":"Windows 10 操作系统","summary":"操作系统特征、Windows界面、文件管理、系统设置与维护。","sections":[{"id":"2.1","title":"操作系统概述"},{"id":"2.2","title":"Windows 10 基础"},{"id":"2.3","title":"文件和文件夹管理"},{"id":"2.4","title":"控制面板"},{"id":"2.5","title":"Windows 10 的系统维护"},{"id":"2.6","title":"Windows 10 的实用工具"}]},{"number":3,"title":"字处理软件 Word 2016","summary":"文档编辑、格式排版、表格、图文混排与长文档功能。","sections":[{"id":"3.1","title":"使用 Office 2016 应用程序"},{"id":"3.2","title":"Word 2016 的基本操作"},{"id":"3.3","title":"文档格式化与排版"},{"id":"3.4","title":"表格制作"},{"id":"3.5","title":"图文混排"},{"id":"3.6","title":"文档的保护与打印"},{"id":"3.7","title":"Word 2016 的高级应用"}]},{"number":4,"title":"电子表格系统 Excel 2016","summary":"工作表操作、公式与函数、格式化、数据处理和图表。","sections":[{"id":"4.1","title":"Excel 2016 概述"},{"id":"4.2","title":"Excel 2016 的基本操作"},{"id":"4.3","title":"Excel 公式与函数"},{"id":"4.4","title":"格式化工作表"},{"id":"4.5","title":"数据处理"},{"id":"4.6","title":"使用图表"}]},{"number":5,"title":"演示文稿软件 PowerPoint 2016","summary":"幻灯片组织、外观、动画、切换与放映设置。","sections":[{"id":"5.1","title":"PowerPoint 2016 基础"},{"id":"5.2","title":"幻灯片页面设计"},{"id":"5.3","title":"幻灯片页面外观的修饰"},{"id":"5.4","title":"动画效果和动作设置"},{"id":"5.5","title":"播放和打印演示文稿"},{"id":"5.6","title":"演示文稿的其他功能"}]},{"number":6,"title":"计算机网络及网页制作","summary":"网络结构、Internet应用、HTML、网页与信息检索。","sections":[{"id":"6.1","title":"计算机网络概述"},{"id":"6.2","title":"计算机网络系统"},{"id":"6.3","title":"Internet 基础和应用"},{"id":"6.4","title":"网页、网页制作及 HTML 简介"},{"id":"6.5","title":"信息检索"}]},{"number":7,"title":"数字多媒体技术基础","summary":"多媒体特征、媒体元素、图像格式、颜色和视频。","sections":[{"id":"7.1","title":"数字多媒体技术概述"},{"id":"7.2","title":"数字多媒体系统组成及常用软件"},{"id":"7.3","title":"常用多媒体制作软件"}]},{"number":8,"title":"信息安全","summary":"安全属性、恶意软件、防火墙、密码技术和信息伦理。","sections":[{"id":"8.1","title":"信息安全概述"},{"id":"8.2","title":"计算机病毒"},{"id":"8.3","title":"防火墙"},{"id":"8.4","title":"Windows 10 操作系统安全"},{"id":"8.5","title":"信息伦理"}]},{"number":9,"title":"信息技术前沿","summary":"虚拟现实、云计算、物联网、区块链与人工智能。","sections":[{"id":"9.1","title":"虚拟现实和增强现实"},{"id":"9.2","title":"云计算和高性能计算"},{"id":"9.3","title":"物联网技术"},{"id":"9.4","title":"大数据技术"},{"id":"9.5","title":"区块链技术"},{"id":"9.6","title":"人工智能"},{"id":"9.7","title":"量子通信"},{"id":"9.8","title":"元宇宙"}]},{"number":10,"title":"数据库技术基础","summary":"关系数据库、数据库管理系统、关系运算、SQL与NoSQL。","sections":[{"id":"10.1","title":"数据库技术基础"},{"id":"10.2","title":"数据库管理系统"},{"id":"10.3","title":"数据库设计与 NoSQL"}]},{"number":11,"title":"计算思维","summary":"计算思维、算法表示、算法特征和基本控制结构。","sections":[{"id":"11.1","title":"计算思维"},{"id":"11.2","title":"计算思维与算法"},{"id":"11.3","title":"算法的控制结构"},{"id":"11.4","title":"面向对象程序设计"},{"id":"11.5","title":"基础算法设计思想"}]}],"notes":[{"q":6,"chapter":3,"section":"3.2","type":"单选","topic":"文档视图","title":"Word视图、标题结构与导航窗格","trigger":"真题从视图用途、标题重组和导航窗格无标题的故障现象考查长文档结构。","conclusion":"先给正文标题建立层级，再用大纲视图组织内容、导航窗格定位标题，最后用打印布局核对实际页面。只放大、加粗文字不会建立标题结构。","points":["建立层级：给一级、二级标题分别应用“标题1”“标题2”；自定义标题可设置相应大纲级别。不要把整篇标题都设为同一级。","导航窗格：视图→导航窗格→标题。单击标题定位；在标题列表中拖动标题可连同所属内容调整顺序。表格、文本框、页眉和页脚中的标题不在这个列表中。","自动目录：引用→目录。默认自动目录依据标题层级生成；自定义目录还可配置样式、大纲级别或目录条目。","目录更新：只改变分页时可更新页码；新增、删除或改名标题后应更新整个目录。直接编辑目录显示文字不能替代修改正文标题。","草稿视图侧重文字，不显示图片、页眉页脚；桌面Word的Web版式仍可编辑文字和查看图片，不按纸张分页。不要把Web版式误当成只读网页。"],"boundary":"导航窗格、正文标题和自动目录是相关的三个对象；某处看起来像标题，不能保证它会被导航或目录收录。","id":"merged-5","sources":[{"year":2020,"q":6,"type":"单选"},{"year":2023,"q":8,"type":"单选"},{"year":2023,"q":66,"type":"分析"},{"year":2026,"q":27,"type":"多选"},{"year":2021,"q":41,"type":"操作","page":6},{"year":2021,"q":45,"type":"操作","page":7},{"year":2021,"q":46,"type":"操作","page":7}],"keys":["2020-6","2023-8","2023-66","2026-27","2021-41","2021-45","2021-46"],"comparison":{"headers":["视图","主要用途","查看页面效果"],"rows":[["打印布局","编辑文档并检查分页、页眉页脚","适合核对打印版式"],["大纲视图","按标题级别升降级、重排内容","重在文档结构"],["草稿视图","集中编辑正文","不显示图片、页眉页脚和完整页面版式"],["Web版式","按网页连续显示，仍可编辑","不按纸张正常分页"],["阅读模式","以屏幕阅读为主","阅读显示不改变文档格式"]]},"searchAliases":["目录不显示标题","导航没有标题","标题不进目录","目录页码不对"]},{"q":10,"target":null,"chapter":3,"section":"3.2","topic":"按样式选择","title":"按同一格式或样式批量选中文本","conclusion":"要删除所有“标题1”文字，应先选中所有匹配的标题段落，再删除内容；清除格式与删除文字是两种操作。","points":["按样式选择：开始→样式，打开目标样式的菜单，选择所有使用该样式的实例，再核对选区。","按外观选择：先选中一个目标，再用开始→选择→选择格式相似的文本。相同外观可能来自不同样式，不能仅凭选中结果认定它们都属于“标题1”。","执行删除前确认选择的是全部目标文字；要调整格式时保留文字，不按Delete。"],"boundary":"不要把“删除样式”当作删除所有标题内容。","type":"单选","trigger":"从按样式选择的判断与应用整理。","id":"y2022q10","sources":[{"year":2022,"q":10,"type":"单选"}],"keys":["2022-10"],"comparison":{"headers":["做法","文字内容","格式或样式"],"rows":[["选中后按Delete","删除所选内容","不是修改样式定义"],["清除格式","保留内容","移除相应格式"],["修改“标题1”样式","保留内容","更新使用该样式的格式规则"]]}},{"q":55,"chapter":3,"section":"3.2","type":"操作","topic":"校对标记","title":"校对波浪线提示可能的问题，不属于打印正文","trigger":"题目解释Word正文下方红色、绿色波浪线为何不出现在打印稿。","conclusion":"拼写、语法检查的波浪线是编辑提示，不是文档下划线，正常打印正文时不会把这些提示线印出来。","points":["红色波浪线通常提示可能的拼写问题；语法等提示颜色会随版本和校对组件变化，应根据校对建议判断，不能只背颜色。","右击标记可查看建议、忽略提示；已确认正确的专有词可加入词典。提示是待核查线索，不代表原文一定错误。","审阅→拼写和语法，或按F7启动检查；大量误报时先核对所选文字的校对语言。"],"boundary":"字体设置中的单下划线、双下划线属于正文格式，会打印；隐藏校对提示也不等于改正原文。","id":"y2023q55","sources":[{"year":2023,"q":55,"type":"操作"}],"keys":["2023-55"]},{"q":7,"chapter":3,"section":"3.2","type":"单选","topic":"文本选择","title":"Ctrl+Shift+End选到文档末尾","trigger":"题目要求从当前插入点一次选择到Word文档末尾。","conclusion":"在Word中，Ctrl+Shift+End从当前插入点扩展选择到文档末尾；Ctrl+End只移动光标而不选择。","points":["Shift负责扩展选择，Ctrl+方向或Home/End负责跨更大范围移动。","Ctrl+Shift+Home可从当前位置选择到文档开头。","Shift+End通常只选择到当前行末。"],"boundary":"Home/End的作用范围会受Ctrl和Shift组合影响，答题时要同时检查“移动到哪里”和“是否选择”。","id":"y2024q7","sources":[{"year":2024,"q":7,"type":"单选"}],"keys":["2024-7"]},{"q":9,"chapter":3,"section":"3.2","type":"单选","topic":"查找替换","title":"查找替换可批量处理文本、特殊字符与格式","trigger":"真题从删除空段、段落对齐和批量清除字符格式考查查找替换。","conclusion":"查找内容决定“找谁”，替换文字和替换格式决定“改成什么”。同样文字替换回去并指定常规字形，可以只改变匹配文字的字形。","points":["指定文字恢复常规：按Ctrl+H，在“查找内容”和“替换为”都输入目标文字；将光标放到“替换为”，再选更多→格式→字体→常规。","核对两个文本框下方的格式摘要。查找一侧残留的字体、样式等条件会缩小匹配范围；用“不限定格式”清除不需要的条件，再设置本次条件。","只替换格式时，可让查找与替换文本框留空，分别设置查找格式和目标格式；不要将“替换为空”与“留空但指定替换格式”混为一谈。","清理连续空段时，在未启用“使用通配符”的条件下，可把^p^p替换为^p。若有更多连续空段，需重复处理；若段内还有空格或制表符，则不等于连续两个段落标记。","查找替换可改变匹配内容的字符或段落格式，也可匹配样式，但不能代替在样式库中修改样式定义。嵌入型图片跟随所在段落对齐，调整图片所在段落可使其居中。","“常规”同时取消加粗和倾斜；题目只要求取消某一种效果时，应核对是否需要保留其他效果。先检查匹配和替换范围，再执行全部替换。"],"boundary":"相同文字换回去而未设置替换格式，不保证去掉原有加粗；格式条件放错一侧，会改变查找范围或替换结果。","id":"y2025q48","sources":[{"year":2024,"q":9,"type":"单选"},{"year":2025,"q":48,"type":"操作"}],"keys":["2024-9","2025-48"],"comparison":{"headers":["目标","查找设置","替换设置"],"rows":[["改文字","输入原词","输入新词"],["删除指定文字","输入原词","留空且不指定替换格式"],["指定文字恢复常规","输入目标词","相同词＋字形常规"],["只改格式","文本留空＋原格式","文本留空＋目标格式"]]}},{"q":4,"chapter":3,"section":"3.3","type":"单选","topic":"多级列表","title":"项目符号、编号与多级列表","trigger":"四道题从入口、层级调整和缩进排错考查Word列表功能。","conclusion":"项目符号适合无序内容，编号适合有序内容；多级列表用编号位置、文本缩进和制表位共同控制层级版式。","points":["项目符号、编号和多级列表位于开始→段落。无先后关系用项目符号；顺序步骤用编号；章节层次用多级列表。","在列表项文本开头，Tab通常降一级、Shift+Tab通常升一级；行为还受自动调整缩进设置影响。也可在多级列表菜单中使用“更改列表级别”。","一级“1.”与二级“1.1”要建立真正层级。只增大左缩进，未必改变列表级别；只改编号字体，也不改变层级。","编号错位时分别检查编号对齐位置、文本缩进位置和编号后的制表位；不要用连续空格手工补齐。","自定义项目符号可使用符号或图片；符号可设置字体、颜色。编号可设置样式和起始值，不必逐项手改数字。"],"boundary":"不要用空格手工对齐多级编号；普通正文中的Tab可能只是插入制表符。","version":"已转换为Word 2016","id":"merged-8","sources":[{"year":2020,"q":4,"type":"单选"},{"year":2026,"q":56,"type":"分析"},{"year":2026,"q":57,"type":"分析"},{"year":2026,"q":58,"type":"分析"}],"keys":["2020-4","2026-56","2026-57","2026-58"]},{"q":41,"chapter":3,"section":"3.3","type":"操作","topic":"分节页眉","title":"页眉由节、链接状态与首页/奇偶页选项共同决定","trigger":"真题从同节页眉差异、普通页眉输入和长文档分节页眉考查真实规则。","conclusion":"先用分节确定不同内容的范围，再分别管理页眉和页脚的链接；首页不同、奇偶页不同会增加独立的页眉页脚类型。","points":["进入编辑：在打印布局中双击页面顶部，或用插入→页眉→编辑页眉。输入内容前确认当前页属于哪一节、哪一种页眉。","新节默认可能沿用前一节。看到“与上一节相同”时，先取消“链接到前一节”，再修改新节内容，否则可能同时改到前节。","页眉与页脚分别链接；首页页眉、奇数页页眉、偶数页页眉也各自链接到前一节的相同类型。只断开一种，不会自动断开其余类型。","封面、目录均无页眉，而正文单独设置：在正文前插入“下一页”分节符，再断开正文相应页眉链接。若正文页码位于页脚，还要单独检查页脚链接。","正文从1编号：在正文节插入页码，打开“设置页码格式”，选择起始页码1。取消链接改变的是页眉页脚内容的继承；起始页码决定编号。"],"boundary":"“首页不同”处理的是一节的首页，不能单独让封面和目录两页都无页眉；分页符换页但不建立新的节。","version":"已转换为Word 2016","id":"y2020q41","sources":[{"year":2020,"q":41,"type":"操作"},{"year":2023,"q":9,"type":"单选"},{"year":2024,"q":56,"type":"操作"},{"year":2021,"q":44,"type":"操作","page":7}],"keys":["2020-41","2023-9","2024-56","2021-44"],"comparison":{"headers":["设置","控制什么","不能代替什么"],"rows":[["分节符","划分独立设置范围","不会自动取消前节链接"],["链接到前一节","当前类型沿用前节内容","不会自动改起始页码"],["首页不同","本节首页单独一套内容","不能处理任意多页前置内容"],["奇偶页不同","奇数页、偶数页分开","不能自动按章节填写不同文字"]]}},{"q":42,"chapter":3,"section":"3.3","type":"操作","topic":"字符与段落格式","title":"显示、字符格式与段落对齐要分清","trigger":"真题从字号、上标、字形、下划线、显示缩放和段落对齐反复考查格式边界。","conclusion":"先判断改变的对象：字符格式管字，段落格式管整段排布，显示比例管屏幕查看。三者都可能让文字“看起来变了”，但对打印的影响不同。","points":["上标抬高并缩小所选字符，下标降低并缩小所选字符。Word快捷键：上标Ctrl+Shift+=，下标Ctrl+=；它们改变格式，不是把内容改成另一种Unicode字符。","字体对话框可设置字形、字号、单/双下划线、删除线和着重号；校对波浪线只是提示，不属于这些打印格式。","字体颜色改变字本身；文本突出显示颜色像荧光笔标记字符背景；段落底纹按段落范围着色，页面颜色改变页面背景。","两端对齐通常不拉伸自然结束的末行；分散对齐可让末行也分散到左右边界。判断时检查最后一行，并区分自然段结束与手动换行。","标题要求居中且无首行或悬挂偏移：设置段落居中，并把特殊格式设为“无”；若已有左右缩进，还需核对它们是否符合要求。","全角１２３与半角123是不同字符。选中文字后可在中文Word的开始→字体→更改大小写→半角中转换；格式刷只复制格式，不做这种字符转换。"],"boundary":"要求“打印时字更大”应改字号，要求“屏幕上看得更大”可改缩放；先确认目标，不能用同一个按钮替代。","id":"merged-7","sources":[{"year":2020,"q":42,"type":"操作"},{"year":2023,"q":51,"type":"操作"},{"year":2024,"q":52,"type":"操作"},{"year":2025,"q":29,"type":"多选"},{"year":2025,"q":46,"type":"操作"},{"year":2026,"q":46,"type":"操作"},{"year":2022,"q":53,"type":"操作"},{"year":2021,"q":42,"type":"操作","page":6},{"year":2021,"q":43,"type":"操作","page":6}],"keys":["2020-42","2023-51","2024-52","2025-29","2025-46","2026-46","2022-53","2021-42","2021-43"],"comparison":{"headers":["层级","典型项目","影响打印"],"rows":[["字符格式","字体、字号、字形、上下标、下划线","会改变字的排版或外观"],["段落格式","对齐、缩进、段前段后、行距","会改变段落排布"],["显示比例","100%改为150%","不改变文档打印尺寸"]]}},{"q":43,"chapter":3,"section":"3.3","type":"操作","topic":"段落缩进与换行","title":"首行缩进属于段落，手动换行不会新建段落","trigger":"真题从手工空格和手动换行符考查首行缩进的作用范围。","conclusion":"首行缩进作用于每个段落的第一行。Enter建立新段落，Shift+Enter只在原段落内换行，自动换行也不会重算一个新段落的首行。","points":["设置2字符首行缩进：选中正文段落→开始→段落对话框→缩进和间距→特殊格式“首行缩进”→度量值“2字符”。","在开始→段落中开启“显示/隐藏编辑标记”：段落标记是¶，手动换行标记是弯箭头。以标记判断结构，不能只看视觉上是否另起一行。","首行缩进只改变第一行；左缩进改变整段的左侧位置；悬挂缩进使首行之外的各行相对缩进。","不要靠段首空格凑2字符。空格属于内容，会受字体与字号影响，也不能给每个新段落建立稳定的缩进规则。"],"boundary":"下一行是否执行首行缩进，取决于它是否属于新段落；按Enter后的新段还受“后续段落样式”等样式规则影响。","id":"y2020q43","sources":[{"year":2020,"q":43,"type":"操作"},{"year":2024,"q":51,"type":"操作"}],"keys":["2020-43","2024-51"],"comparison":{"headers":["换行方式","是否新段落","首行缩进"],"rows":[["文字到行末自动换行","否","仍按原段落的非首行排布"],["Shift+Enter","否","不会因换行重新成为首行"],["Enter","是","按新段落的格式规则执行"]]}},{"q":44,"chapter":3,"section":"3.3","type":"操作","topic":"分栏与页面查看","title":"正文分栏会改变排版，页面并排只改变屏幕查看","trigger":"真题从两栏排版和多页并排阅读考查两个容易混淆的功能。","conclusion":"选中文本后用“布局→栏→两栏”建立报刊式文本流；多页/并排查看只改变屏幕显示，不改变打印版式。","points":["只给一段正文分栏：先选中目标文字，再用布局→栏→两栏；“更多栏”中核对“应用于”范围。Word可用连续分节符隔离所选部分。","文字通常按左栏从上向下，再流向右栏；要提前转到下一栏可插入分栏符，不必用大量空行顶过去。","更多栏可设置栏数、栏宽、间距和分隔线；不等栏宽需要取消等宽设置后分别调整。","分栏会改变正文排版和打印结果；视图中的多页显示、并排查看只改变屏幕查看方式。"],"boundary":"插入表格模拟两栏不等于真正分栏；页面并排也不会把正文自动变成两栏。","version":"已转换为Word 2016","id":"y2020q44","sources":[{"year":2020,"q":44,"type":"操作"},{"year":2023,"q":53,"type":"操作"}],"keys":["2020-44","2023-53"]},{"q":61,"chapter":3,"section":"3.3","type":"综合","topic":"分节","title":"只改变一页纸张方向","trigger":"题目要求让表格所在页横向，而前后页面仍为纵向。","conclusion":"纸张方向按节设置。只让中间一页横向，要把该页内容单独分成一节，并确认横向仅应用于这一节。","points":["手动分节：在目标页内容前插入布局→分隔符→下一页分节符；在目标内容后再插入下一页分节符，使后文重新成为另一节。","把光标放在目标节，打开页面设置，设为横向并确认“应用于：本节”；再检查前后两节仍为纵向。","也可先选择需要横向的内容，在页面设置中选横向，并把“应用于”设为“所选文字”；Word会为不同方向建立所需分节边界。","节还可分别控制页边距、页眉页脚和页码设置；但页眉页脚是否沿用前节，要另外看链接状态。"],"boundary":"如果只在目标页之前分节而没有隔离后文，横向可能继续影响后面的多页；操作后必须检查相邻页。","id":"y2020q61","sources":[{"year":2020,"q":61,"type":"综合"}],"keys":["2020-61"],"comparison":{"headers":["分隔方式","作用","能否单独隔离纸张方向"],"rows":[["分页符","从新页继续同一节","不能"],["下一页分节符","从新页开始新节","可以划出节边界"],["连续分节符","在当前页开始新节","常用于同页分栏等设置"]]}},{"q":56,"target":null,"page":9,"chapter":3,"section":"3.3","topic":"模板与样式","title":"样式统一一份文档，模板给多份文档共同起点","conclusion":"把标题、正文等格式定义为样式，再保存为模板，让不同文档从同一套规范开始。","points":["先明确标题、正文的字体、字号、段落间距和缩进，再分别建立样式；修改样式可更新使用它的内容，但已有直接格式可能仍覆盖某些属性，要检查例外。","把样式、页面设置和固定内容保存为模板；不含宏常用.dotx，含宏用.dotm，普通文档常用.docx。","从模板新建的是独立文档。修改新文档正文不会默认写回模板，修改模板也不会默认更新已经创建的所有旧文档。","实施顺序：建立样式→保存模板→基于模板新建文档→应用对应样式→检查局部例外。"],"boundary":"保存模板不意味着所有旧文档自动更新；仍需新建时选模板或把相应样式应用到旧文档。","type":"分析","trigger":"围绕模板与样式的识别、应用与易错边界整理。","id":"y2021q56","sources":[{"year":2021,"q":56,"type":"分析"},{"year":2021,"q":57,"type":"分析","page":10}],"keys":["2021-56","2021-57"],"comparison":{"headers":["工具","适合什么","维护方式"],"rows":[["直接格式","某个词、某段的局部例外","只改选中内容"],["格式刷","把已有格式复制到少量目标","源格式以后改变，目标不自动跟随"],["样式","一份文档中同类内容统一","修改样式规则"],["模板","多份新文档共用起点","基于模板创建独立文档"]]}},{"q":24,"target":null,"chapter":3,"section":"3.3","topic":"标尺与缩进","title":"标尺四个缩进标记控制不同的行","conclusion":"拖标尺前先确定要移动第一行、其余行、整段左边界还是右边界。左下方方块会带着首行和悬挂标记一起移动，保留它们的相对距离。","points":["先选中需要调整的段落，在视图中显示标尺，再拖相应标记；否则可能只修改光标所在段落。","首行比其余行更靠右表现为首行缩进；首行比其余行更靠左表现为悬挂缩进。不要把三角形朝向直接当作“向左/向右缩进”。","拖页边距交界改变页面可排版区域；拖缩进标记改变段落相对该区域的位置。行距、段前和段后间距不由水平标尺这些标记控制。"],"boundary":"先分清“第一行”“其余行”“整段”，不要把首行缩进和悬挂缩进方向记反。","type":"多选","trigger":"从标尺与缩进的判断与应用整理。","id":"y2022q24","sources":[{"year":2022,"q":24,"type":"多选"}],"keys":["2022-24"],"comparison":{"headers":["标记","拖动后改变","其余部分"],"rows":[["左上三角","第一行的起点","其余行起点保留"],["左下三角","除首行外各行的起点","首行起点保留"],["左下方块","整个段落的左侧位置","首行与其余行的差值保留"],["右端三角","段落右边界","不等于页面右页边距"]]}},{"q":70,"target":null,"chapter":3,"section":"3.3","topic":"页面背景","title":"图片水印、页面背景和衬于文字下方各有入口","conclusion":"Logo放在正文后方，可用图片水印、页面颜色的图片填充，或普通图片设为衬于文字下方。","points":["图片水印适合重复出现的淡化标识，在“设计→水印”设置。","普通图片需设置环绕、大小和位置，不会天然推广到每页。","页面背景图片能否打印，还需检查Word打印背景颜色和图像选项。"],"boundary":"页面边框控制边缘线条，不负责把Logo作为整页背景；背景也不应遮挡正文。","type":"综合","trigger":"从页面背景的判断与应用整理。","id":"y2022q70","sources":[{"year":2022,"q":70,"type":"综合"}],"keys":["2022-70"]},{"q":52,"chapter":3,"section":"3.3","type":"操作","topic":"样式","title":"统一修改同级标题应直接修改样式","trigger":"题目要求让所有“标题1”段落统一增加段前20磅。","conclusion":"在样式库中右击“标题1→修改→格式→段落”，把段前设为20磅，可一次更新所有使用该样式的标题。","points":["先检查目标段落确实使用“标题1”；仅手动加粗、放大成相同外观的段落不会因此受到样式修改。","开始→样式，右击标题1→修改→格式→段落，把段前设为20磅，确认后核对所有同级标题。","样式可同时包含字符与段落格式，后续应用同一样式的标题也会继承该规则；若某段仍不同，检查是否存在覆盖样式的直接格式。","需要把新规则用于以后基于模板创建的文档时，再明确设置模板保存范围；修改当前文档不等于改了所有旧文件。"],"boundary":"格式刷适合少量复制，不是全局规则；修改某一段的直接格式也不会自动更新所有同级标题。","id":"y2023q52","sources":[{"year":2023,"q":52,"type":"操作"}],"keys":["2023-52"]},{"q":54,"chapter":3,"section":"3.3","type":"操作","topic":"页眉边框","title":"页眉横线应作为段落下边框设置","trigger":"题目要求改变页眉自动横线的颜色和宽度。","conclusion":"把光标放入页眉段落，打开“边框和底纹→边框”，设置线型、颜色和宽度，并把下边框应用于段落。","points":["横线通常是页眉段落的下边框，不是可拖动的普通直线形状。","“应用于：段落”决定边框随页眉段落宽度延伸。","预览区只保留下边框可避免四周都出现线。","删除页眉文字后横线仍在时，应检查页眉段落下边框；选中页眉段落，用“开始→边框→无框线”移除，不要反复按Delete找不存在的图片。","也可把“页眉”样式的段落边框改为无；使用该样式且未被直接格式覆盖的页眉段落会随之更新。"],"boundary":"修改页面边框会影响整页四周，修改下划线只作用于文字，两者都不能替代页眉段落边框。","id":"y2024q54","sources":[{"year":2024,"q":54,"type":"操作"},{"year":2022,"q":51,"type":"操作"}],"keys":["2024-54","2022-51"]},{"q":66,"chapter":3,"section":"3.3","type":"分析","topic":"行距与图片","title":"固定行距过小会裁切嵌入型图片","trigger":"题目描述按Enter后粘贴图片，图片为嵌入型却只能显示一部分。","conclusion":"嵌入型图片占据文本行；若段落设置了小于图片高度的固定值行距，行框会裁切图片。","points":["改为单倍、多倍或“最小值”行距可让行高随对象增大。","若必须用固定值，应把磅值调到足以容纳图片。","图片环绕方式不是唯一原因，应先检查段落行距。"],"boundary":"“固定值”与“最小值”不同：固定值锁死行高，最小值允许内容更高时自动扩展。","id":"y2024q66","sources":[{"year":2024,"q":66,"type":"分析"}],"keys":["2024-66"]},{"q":47,"chapter":3,"section":"3.3","type":"操作","topic":"中文版式","title":"中文与数字、中文与西文的自动间距分别控制","trigger":"题目要求解释相同文字为何多占一行并选择压缩方法。","conclusion":"中文与数字、中文与西文是两个独立选项。文段含“10亿年”等数字时，应检查“自动调整中文与数字的间距”。","points":["入口：开始→段落对话框启动器→中文版式→字符间距。","取消中文与数字间距，影响汉字和数字交界处；中文与西文选项影响汉字与拉丁字母交界处。","自动间距不同于手动输入的空格；关闭自动间距不会删除真实空格，也不会改字号。","行数是否减少还取决于字体、字号和行宽，不能保证每个文段都恰好从三行变两行。"],"boundary":"为挤进行数而任意缩放字符会损害可读性，应先查明真正的版式来源。","id":"y2026q47","sources":[{"year":2026,"q":47,"type":"操作"}],"keys":["2026-47"]},{"q":60,"chapter":3,"section":"3.4","type":"综合","topic":"表格边框","title":"给表格设置全部框线","trigger":"题目比较绘制表格、边框菜单和表格属性等设置全部框线的方法。","conclusion":"选中表格后使用“开始”或“表格工具-设计”中的边框菜单设置“所有框线”最直接。","points":["边框可作用于单元格、所选区域或整张表格。","表格属性中的“边框和底纹”可精确设置线型、颜色、宽度和应用范围。","绘制表格适合补画局部线条，不适合为已有大表逐条重画。"],"boundary":"边框快捷菜单按当前选区应用；也可把光标置于任意单元格，经表格属性→边框和底纹，把“应用于”设为“表格”。光标位于表格内即可显示表格工具，不要求先选中整表。","version":"已转换为Word 2016","id":"y2020q60","sources":[{"year":2020,"q":60,"type":"综合"}],"keys":["2020-60"]},{"q":62,"chapter":3,"section":"3.4","type":"综合","topic":"跨页表格","title":"跨页表格重复标题行","trigger":"题目要求表格跨多页时每页顶部都显示标题行。","conclusion":"让跨页表格自动重复表头，应选中从第一行开始的连续标题行，再用表格工具→布局→重复标题行。","points":["重复行必须包含表格第一行；多行表头应连续选中，不能只选表格中部某一行作为重复表头。","也可打开表格属性→行，勾选“在各页顶端以标题行形式重复出现”。","该效果在打印布局和打印结果中查看；后续页的重复标题由首段表头生成，应修改第一页的原始标题行。","表格因内容自然跨页时会重复标题；在表格内部手动插入分页符不会得到同样的自动重复效果。"],"boundary":"“表格样式选项→标题行”主要影响样式外观，不等于跨页重复标题；页面页眉也不是表格表头。","version":"已转换为Word 2016","id":"y2020q62","sources":[{"year":2020,"q":62,"type":"综合"}],"keys":["2020-62"]},{"q":63,"chapter":3,"section":"3.4","type":"综合","topic":"表格对齐","title":"整张表格居中与单元格内容居中","trigger":"题目比较段落居中、表格属性和表格工具中的水平居中。","conclusion":"整表在页面中居中，应设置表格对齐方式；单元格水平居中只改变格内内容。","points":["整表居中：右击表格→表格属性→表格→对齐方式“居中”。它改变表格对象相对排版区域的位置。","格内文字水平居中：选择目标单元格内容，使用开始→段落→居中；文字在各自单元格内移动，表格宽度与位置不因此改变。","格内水平与垂直位置一起设置：使用表格工具→布局→对齐方式的九种对齐选项；表格属性→单元格也可设置垂直对齐。","确认结果时观察表格左右留白和文字在单元格中的位置，分别判断两个目标是否达到。"],"boundary":"先分清“表格这个对象居中”还是“单元格里的文字居中”，两者按钮和结果不同。","version":"已转换为Word 2016","id":"y2020q63","sources":[{"year":2020,"q":63,"type":"综合"}],"keys":["2020-63"],"comparison":{"headers":["要求","规范入口","观察结果"],"rows":[["整张表格居中","表格属性→表格→居中","表格左右留白对称"],["格内文字水平居中","所选内容→段落居中","字在单元格内左右居中"],["格内文字上下居中","表格工具→布局→对齐方式","字在单元格内垂直居中"]]}},{"q":69,"target":null,"chapter":3,"section":"3.4","topic":"链接与嵌入","title":"链接Excel表格可随源数据更新，嵌入保留独立副本","conclusion":"希望Word表格跟随Excel变化，应采用粘贴链接或链接对象；普通粘贴、嵌入和图片通常不会自动跟随源文件。","points":["复制Excel区域后，在Word选择“链接并保留源格式”或“链接并使用目标样式”；也可用开始→粘贴→选择性粘贴→粘贴链接。","更新链路：修改并保存Excel源数据→Word刷新链接或按提示更新→核对Word中的值。更新时机仍受自动更新和安全设置影响。","链接依赖源文件位置和访问权限；移动、重命名或失去权限可能使更新失败。Word暂时还能显示旧值，不代表链接正常。","源格式/目标格式决定外观，链接/嵌入决定数据关系；两者要分别判断。"],"boundary":"链接是数据关系，源格式/目标格式是外观选择，两者不是同一个维度。","type":"综合","trigger":"从链接与嵌入的判断与应用整理。","id":"y2022q69","sources":[{"year":2022,"q":69,"type":"综合"}],"keys":["2022-69"],"comparison":{"headers":["粘贴方式","源Excel修改后","Word里保存什么"],"rows":[["粘贴链接","允许并刷新后可更新","链接关系及显示内容"],["嵌入Excel对象","不跟随源文件变化","可独立编辑的Excel副本"],["普通表格粘贴","不跟随源文件变化","Word表格内容"],["图片","不跟随源文件变化","图像，不能按单元格修改"]]}},{"q":6,"chapter":3,"section":"3.4","type":"单选","topic":"删除表格","title":"Word表格的转换、计算、排序与删除","trigger":"真题反复辨析选中整张Word表格后Delete与Backspace的不同结果。","conclusion":"选中整张表格后按Delete通常只清空单元格内容并保留结构；按Backspace或使用“删除表格”命令可删除结构。","points":["选择整表：使用表格左上角移动控点。按Delete通常只清空内容；明确删除表格结构可用表格工具→布局→删除→删除表格。整表确已选中时，Backspace也可删除表格。","文本转表格：插入→表格→文本转换成表格。用制表符、逗号等分隔列，用段落标记分隔行；先核对每行分隔符数量和目标列数。","排序：表格工具→布局→数据→排序。指定主要关键字、数据类型、升降序及有无标题行；文字可按可用的拼音、笔划等规则排序。","计算：把光标放入结果单元格，再用表格工具→布局→公式。=SUM(ABOVE)用于上方，=SUM(LEFT)用于左方；需精确范围时也可使用单元格引用。","Word表格公式是域。源数值修改后，应选择结果按F9或右击更新域，不能假定会像Excel一样立即重算。使用位置参数求和时，参与范围中的空单元格可先填0，避免范围或结果异常。"],"boundary":"同样一个Delete或Backspace，光标、文字选区、单元格选区与整表选区会得到不同结果；先确认选中了什么。","id":"y2024q8","sources":[{"year":2023,"q":6,"type":"单选"},{"year":2024,"q":8,"type":"单选"}],"keys":["2023-6","2024-8"]},{"q":45,"chapter":3,"section":"3.5","type":"操作","topic":"图片尺寸","title":"图片尺寸、纵横比与裁剪","trigger":"两道连续操作题考查为何宽高不能同时指定，以及如何在尺寸要求和不变形之间取舍。","conclusion":"锁定纵横比时修改一边会按比例改变另一边；需要精确尺寸且不失真时，应先裁剪到目标比例再缩放。","points":["关闭纵横比可以强制输入宽高，但可能拉伸图像。","裁剪改变可见范围，缩放改变显示尺寸，两者解决的问题不同。","实际排版应优先保持人物和图形不变形。","2020年题设原图高8.5 cm、宽6 cm。锁定比例后，高改为6 cm时宽约4.24 cm；宽改为5 cm时高约7.08 cm。目标高6 cm、宽5 cm的宽高比为5∶6，与原图6∶8.5不同。"],"boundary":"考试若只问机械步骤可能选择取消锁定；规范成品还要检查是否产生视觉失真。","id":"merged-9","sources":[{"year":2020,"q":45,"type":"操作"},{"year":2020,"q":46,"type":"操作"}],"keys":["2020-45","2020-46"]},{"q":54,"target":null,"chapter":3,"section":"3.5","topic":"艺术字","title":"用艺术字创建弯曲、描边和填充的装饰文字","conclusion":"艺术字是可编辑的文字对象，可设置文字填充、轮廓和文字效果；弯曲文字应使用文字效果中的转换。","points":["“插入→艺术字”创建对象并输入文字。","选中艺术字后，在绘图工具格式中调整文字效果；跟随路径/转换改变文字排列形态。","普通字符加粗或放大不会让整段文字沿弧线排列。"],"boundary":"文字效果与形状效果不同；艺术字仍可改文字，转成图片后不再是同一编辑对象。","type":"操作","trigger":"从艺术字的判断与应用整理。","id":"y2022q54","sources":[{"year":2022,"q":54,"type":"操作"}],"keys":["2022-54"]},{"q":7,"chapter":3,"section":"3.5","type":"单选","topic":"公式工具","title":"Word公式应从“插入→公式”创建和编辑","trigger":"题目辨析Word 2016公式工具的入口、显示方式和结构编辑。","conclusion":"Word 2016应通过“插入→公式”或Alt+=插入公式，随后在公式工具中搭建分数、上下标、根式等结构。","points":["公式既可与正文位于同一行，也可转换为独立显示。","选中已有公式后可继续修改结构、符号与专业/线性显示。","常用公式可以保存到公式库重复使用。"],"boundary":"“插入→对象”可嵌入某些对象，但不是Word内置公式工具的标准入口。","id":"y2023q7","sources":[{"year":2023,"q":7,"type":"单选"}],"keys":["2023-7"]},{"q":53,"chapter":3,"section":"3.5","type":"操作","topic":"图片环绕","title":"图片环绕取决于对象是嵌入型还是浮动型","trigger":"真题从环绕菜单入口和版面结果考查图片与正文关系。","conclusion":"嵌入型把图片当成文本行里的字符；其他环绕方式让图片成为锚定到段落的浮动对象。先确定是否要绕排，再选环绕边界。","points":["先选中图片，再从图片工具→格式→环绕文字或图片旁的布局选项设置。嵌入型不能像浮动对象一样随意拖到正文任意位置。","四周型按外接矩形绕排；紧密型、穿越型依据环绕轮廓。图片背景、透明区和编辑环绕顶点会影响效果，不能只凭图片外形名称判断。","浮动图片还要区分“随文字移动”和“在页面上固定位置”；环绕方式与位置关系是两个设置，改变前者不等于自动锁定后者。"],"boundary":"文字出现在图片左右两侧可排除嵌入型和上下型；仅凭一张矩形截图，可能无法唯一分辨四周型与紧密型。","id":"y2025q47","sources":[{"year":2024,"q":53,"type":"操作"},{"year":2025,"q":47,"type":"操作"},{"year":2022,"q":52,"type":"操作"},{"year":2021,"q":7,"type":"单选","page":2}],"keys":["2024-53","2025-47","2022-52","2021-7"],"comparison":{"headers":["环绕方式","文字如何排布"],"rows":[["嵌入型","图片像一个字符占据文本行"],["四周型","围绕图片外接矩形"],["紧密型","贴近可用的环绕轮廓"],["穿越型","可进入环绕轮廓允许的内部空隙"],["上下型","只在图片上方、下方排文字"],["衬于文字下方","文字覆盖在图片上方"],["浮于文字上方","图片可能遮住正文"]]}},{"q":56,"chapter":3,"section":"3.5","type":"分析","topic":"对象层级","title":"对象叠放顺序决定箭头是否被形状遮挡","trigger":"两道连续分析题先判断遮挡原因，再要求用绘图工具修复。","conclusion":"浮动对象按层级叠放；矩形位于箭头上层时会遮挡箭头，把箭头置于顶层即可修复。","points":["选择窗格可查看并重排对象层级。","置于顶层或把遮挡对象置于底层都能改变可见关系。","调整层级不会改变对象尺寸和位置。"],"boundary":"文字环绕控制对象与正文的关系，不负责两个浮动形状之间的前后层级。","id":"y2025q56","sources":[{"year":2025,"q":56,"type":"分析"},{"year":2025,"q":57,"type":"分析"}],"keys":["2025-56","2025-57"]},{"q":36,"chapter":3,"section":"3.5","type":"判断","topic":"图形组合","title":"形状可以与图片、艺术字组合","trigger":"题目判断Word中的形状能否与图片或艺术字组合成整体。","conclusion":"形状、图片、艺术字可作为一个组整体操作。先把图片设为非嵌入型环绕，按Ctrl选择至少两个可组合对象，再使用组合命令。","points":["按住Ctrl逐个选择对象外框；点击对象内部文字会进入文字编辑，不能代替选中对象。","入口：图片工具→格式，或绘图工具→格式→排列→组合→组合。按钮不可用时先检查是否至少选中两个对象、是否仍有嵌入型图片。","组合后可统一移动、缩放和旋转；先选组合再选其中对象，仍可修改组内对象，也可取消组合后分别编辑。","对象还应处于可共同选择的文档区域；正文对象与页眉中的对象不能直接当作同一组选择。"],"boundary":"组合不等于合并成一张位图，不会自动删除原对象的可编辑属性；不同对象类型仍有各自限制。","id":"y2026q36","sources":[{"year":2026,"q":36,"type":"判断"}],"keys":["2026-36"]},{"q":71,"target":null,"chapter":3,"section":"3.6","topic":"限制编辑","title":"只锁表格、保留正文可编辑，需要设置编辑例外","conclusion":"Word的限制编辑可设为只读，再把允许修改的正文设置为例外，使表格仍处于受保护区域。","points":["“审阅→限制编辑→仅允许此类型编辑→不允许任何更改（只读）”。","选中允许改动的正文，并设置例外用户；不要把需保护的表格加入例外。","启动强制保护后再测试：正文可改、表格不可改。需密码时妥善保管。"],"boundary":"打开密码控制能否打开文档，不等于按区域限制修改；只选中表格并没有独立的“保护表格”密码命令。","type":"综合","trigger":"从限制编辑的判断与应用整理。","id":"y2022q71","sources":[{"year":2022,"q":71,"type":"综合"}],"keys":["2022-71"]},{"q":5,"chapter":3,"section":"3.7","type":"单选","topic":"题注与引用","title":"题注与交叉引用要配合使用","trigger":"真题从自动表号、图表编号和“先题注、后引用”的操作顺序考查长文档引用。","conclusion":"先为图、表或公式插入题注，再在正文中用交叉引用插入编号，才能在对象增删后统一更新。","points":["为图、表或公式设置自动题注：选择对象→引用→插入题注，确定标签、编号格式和位置；题注编号由域管理。","正文引用图号：引用→交叉引用，选择对应题注及所需内容，例如“仅标签和编号”。选为超链接可支持跳转，但跳转选项不是编号关系本身。","新增、删除或移动对象后，先更新题注编号，再更新引用它的交叉引用域；可选择相关域按F9。跨不同文档区域时要分别核对。","题注还可用于生成图表目录；手工输入的“表1”只是一段普通文字，不会建立自动题注、交叉引用和图表目录的关联。"],"boundary":"自动题注管理对象编号，交叉引用引用已有目标；这两个步骤缺一时，正文编号都可能与对象不一致。","version":"已转换为Word 2016","id":"merged-6","sources":[{"year":2020,"q":5,"type":"单选"},{"year":2023,"q":54,"type":"操作"},{"year":2026,"q":48,"type":"操作"},{"year":2021,"q":6,"type":"单选","page":2}],"keys":["2020-5","2023-54","2026-48","2021-6"]},{"q":55,"target":null,"chapter":3,"section":"3.7","topic":"脚注与尾注","title":"脚注在页底，尾注通常在文末或节末","conclusion":"脚注和尾注由正文引用标记连接说明内容；插入引用后由Word管理编号。","points":["光标放在需解释的文字后，使用“引用→插入脚注”。","新增、移动或删除正文中的引用标记时，编号可自动重新安排。","脚注/尾注用于补充说明；批注用于审阅交流，题注用于给图表编号。"],"boundary":"删除注释应删除正文中的引用标记，不能只擦掉页底说明文字。","type":"操作","trigger":"从脚注与尾注的判断与应用整理。","id":"y2022q55","sources":[{"year":2022,"q":55,"type":"操作"}],"keys":["2022-55"]},{"q":56,"chapter":3,"section":"3.7","type":"操作","topic":"修订","title":"修订记录编辑，接受或拒绝决定最终文本","trigger":"题目要求按正确顺序记录教师的插入、删除并形成最终稿。","conclusion":"先打开“审阅→修订”，再进行编辑；完成后逐项接受或拒绝修订，才能形成最终文本。","points":["开始记录：审阅→修订，再编辑正文；插入、删除和格式更改会作为修订保留。关闭修订只停止记录之后的编辑。","所有标记用于查看完整修订；无标记暂时显示采用修订后的清洁效果，但修订记录仍保存在文档中。","接受插入会保留新增文字，拒绝插入会去掉新增文字；接受删除会真正去掉原文字，拒绝删除会恢复原文字。","批注用于说明与讨论，不直接改正文；比较文档用于找出两个版本的差异，与预先开启修订记录后续操作不同。","交付最终文本前，核对并接受或拒绝已有修订。需要停止记录时再关闭修订；不要只切到无标记就认定清理完成。"],"boundary":"是否记录新修改、是否显示旧记录、是否接受旧修改是三件事；隐藏显示不能代替处理修订。","id":"y2023q56","sources":[{"year":2023,"q":56,"type":"操作"},{"year":2021,"q":8,"type":"单选","page":3}],"keys":["2023-56","2021-8"]},{"q":55,"chapter":3,"section":"3.7","type":"操作","topic":"页码域","title":"在形状中放置光标后插入PAGE域","trigger":"题目要求把页码显示在页眉中的平行四边形形状内。","conclusion":"先进入页眉并在形状文字区内放置插入点，再用“页码→当前位置”或插入PAGE域，页码才会成为形状内的动态内容。","points":["“页面顶端”图库会在预设页眉位置新建页码对象，不保证进入现有形状。","PAGE域显示当前页码，NUMPAGES域显示总页数。","页眉中的形状会随页眉重复，但节之间可有不同设置。"],"boundary":"先选中形状外框与把光标放进形状文字区是不同状态；只有后者能把页码插到形状内部。","id":"y2024q55","sources":[{"year":2024,"q":55,"type":"操作"}],"keys":["2024-55"]},{"q":36,"chapter":3,"section":"3.7","type":"判断","topic":"邮件合并","title":"邮件合并连接数据源，合并域和条件规则生成个性化文档","trigger":"题目判断Word 2016邮件合并的数据源能否选择Word文档。","conclusion":"主文档保存共同内容，数据源按行保存记录，合并域把字段放进指定位置；条件规则可按记录内容生成不同称谓。","points":["数据源可以来自规范的Word表格、Excel、Access、Outlook联系人或文本列表；首行通常是字段名，每条记录对应一个收件人或数据对象。","在邮件→选择收件人→使用现有列表连接数据源，确认表或工作表、字段名及所需收件人，再插入姓名等合并域。","需要按性别生成称谓时，用邮件→规则→如果…那么…否则。字段、比较值和两种输出都要设置，例如性别等于“女”输出“女士”，否则输出“先生”。","预览结果后切换记录，检查姓名、称谓和空缺字段；预览只显示当前记录效果。完成并合并时再选择生成文档、打印或其他合并目标。","生成结果不等于原数据源被改写；也不要把所有收件人的内容手工堆在主文档中。"],"boundary":"数据源需要规则的字段和记录；普通散排正文不能直接替代收件人表。字段值为空或拼写不一致时，条件规则可能走到另一分支。","id":"y2025q36","sources":[{"year":2025,"q":36,"type":"判断"},{"year":2022,"q":56,"type":"操作"}],"keys":["2025-36","2022-56"]}],"sourceCount":460,"years":[2020,2021,2022,2023,2024,2025,2026]};
